CREATE TABLE IF NOT EXISTS "agent_tasks" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "agent_id" uuid NOT NULL,
  "parent_task_id" uuid,
  "status" integer DEFAULT 0,
  "priority" integer DEFAULT 3,
  "payload" json DEFAULT '{}'::json,
  "result" json DEFAULT '{}'::json,
  "error_message" text,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "completed_at" timestamptz,
  "deleted_at" timestamptz,
  "aip_session_id" uuid,
  "aip_task_id" varchar(128) DEFAULT NULL::character varying,
  "aip_task_state" varchar(20) DEFAULT NULL::character varying,
  "owner_user_id" uuid,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "agent_tasks" IS 'Agent任务表。存储Agent执行的任务信息，支持任务嵌套。';
COMMENT ON COLUMN "agent_tasks"."id" IS '任务唯一标识';
COMMENT ON COLUMN "agent_tasks"."agent_id" IS '关联Agent ID';
COMMENT ON COLUMN "agent_tasks"."parent_task_id" IS '父任务ID';
COMMENT ON COLUMN "agent_tasks"."status" IS '状态：0-待处理，1-进行中，2-完成，3-失败';
COMMENT ON COLUMN "agent_tasks"."priority" IS '优先级：1-5';
COMMENT ON COLUMN "agent_tasks"."payload" IS '任务内容(JSON)';
COMMENT ON COLUMN "agent_tasks"."result" IS '任务结果(JSON)';
COMMENT ON COLUMN "agent_tasks"."error_message" IS '错误信息';
COMMENT ON COLUMN "agent_tasks"."creator" IS '创建人';
COMMENT ON COLUMN "agent_tasks"."created_at" IS '创建时间';
COMMENT ON COLUMN "agent_tasks"."updated_at" IS '更新时间';
COMMENT ON COLUMN "agent_tasks"."completed_at" IS '完成时间';
COMMENT ON COLUMN "agent_tasks"."deleted_at" IS '删除时间(软删除)';
COMMENT ON COLUMN "agent_tasks"."aip_session_id" IS 'AIP交互会话ID，关联aip_interaction_session表';
COMMENT ON COLUMN "agent_tasks"."aip_task_id" IS 'AIP任务标识符，符合GB/Z 185.6任务结构';
COMMENT ON COLUMN "agent_tasks"."aip_task_state" IS 'AIP任务状态：accepted/rejected/completed/failed/cancelled/in_progress，符合GB/Z 185.6';
COMMENT ON COLUMN "agent_tasks"."owner_user_id" IS '归属者（委派该任务的真人用户 uctoo_user.id）。与 creator 区分：creator 记执行者（agent 帐号），本列恒记归属真人；历史行允许 NULL。';
CREATE INDEX "idx_agent_tasks_agent_id" ON "agent_tasks" ("agent_id");
CREATE INDEX "idx_agent_tasks_aip_session_id" ON "agent_tasks" ("aip_session_id");
CREATE INDEX "idx_agent_tasks_aip_task_id" ON "agent_tasks" ("aip_task_id");
CREATE INDEX "idx_agent_tasks_owner_user_id" ON "agent_tasks" ("owner_user_id");
CREATE INDEX "idx_agent_tasks_parent_task_id" ON "agent_tasks" ("parent_task_id");
CREATE INDEX "idx_agent_tasks_priority" ON "agent_tasks" ("priority");
CREATE INDEX "idx_agent_tasks_status" ON "agent_tasks" ("status");

