CREATE TABLE IF NOT EXISTS "agents" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "name" varchar(100) NOT NULL,
  "agent_type" varchar(50) NOT NULL,
  "description" text,
  "status" integer DEFAULT 0,
  "config" json DEFAULT '{}'::json,
  "system_prompt" text,
  "tools" json DEFAULT '[]'::json,
  "model" varchar(50),
  "parent_id" uuid,
  "user_id" uuid,
  "color" varchar(20),
  "background" boolean DEFAULT false,
  "memory_scope" varchar(20) DEFAULT 'user'::character varying,
  "isolation_mode" varchar(20),
  "max_turns" integer DEFAULT 200,
  "initial_prompt" text,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "version" varchar(20) DEFAULT '1.0.0'::character varying,
  "author" varchar(100),
  "permissions" json DEFAULT '[]'::json,
  "source_path" varchar(512),
  "sync_status" varchar(32) DEFAULT 'pending'::character varying,
  "last_sync_at" timestamptz,
  "aic" varchar(128) DEFAULT NULL::character varying,
  "identity_status" varchar(20) NOT NULL DEFAULT 'none'::character varying,
  "aip_registered_at" timestamptz DEFAULT NULL::timestamp with time zone,
  "capabilities" jsonb,
  "default_input_types" jsonb,
  "default_output_types" jsonb,
  "discoverable" boolean NOT NULL DEFAULT true,
  "skill_name" varchar(128),
  "profile_skills" json DEFAULT '[]'::json,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "agents" IS 'Agent管理表。存储Agent的基本信息、配置、状态等。';
COMMENT ON COLUMN "agents"."id" IS 'Agent唯一标识';
COMMENT ON COLUMN "agents"."name" IS 'Agent名称';
COMMENT ON COLUMN "agents"."agent_type" IS 'Agent类型(main/sub/analyzer/comparator/grader)';
COMMENT ON COLUMN "agents"."description" IS 'Agent描述';
COMMENT ON COLUMN "agents"."status" IS '状态：0-停用，1-运行，2-暂停';
COMMENT ON COLUMN "agents"."config" IS '配置信息(JSON)';
COMMENT ON COLUMN "agents"."system_prompt" IS '系统提示词';
COMMENT ON COLUMN "agents"."tools" IS '工具列表(JSON数组)';
COMMENT ON COLUMN "agents"."model" IS '模型名称';
COMMENT ON COLUMN "agents"."parent_id" IS '父Agent ID';
COMMENT ON COLUMN "agents"."user_id" IS '关联用户ID';
COMMENT ON COLUMN "agents"."color" IS '显示颜色';
COMMENT ON COLUMN "agents"."background" IS '是否后台运行';
COMMENT ON COLUMN "agents"."memory_scope" IS '内存范围(user/project/local)';
COMMENT ON COLUMN "agents"."isolation_mode" IS '隔离模式(worktree/remote)';
COMMENT ON COLUMN "agents"."max_turns" IS '最大对话轮数';
COMMENT ON COLUMN "agents"."initial_prompt" IS '初始提示';
COMMENT ON COLUMN "agents"."creator" IS '创建人';
COMMENT ON COLUMN "agents"."created_at" IS '创建时间';
COMMENT ON COLUMN "agents"."updated_at" IS '更新时间';
COMMENT ON COLUMN "agents"."deleted_at" IS '删除时间(软删除)';
COMMENT ON COLUMN "agents"."source_path" IS '文件系统实体定义文件的相对路径，作为同步的首要数据唯一标识';
COMMENT ON COLUMN "agents"."sync_status" IS '同步状态: synced(已同步), pending(待同步), error(同步失败), dependency_missing(依赖缺失)';
COMMENT ON COLUMN "agents"."last_sync_at" IS '最后成功同步时间';
COMMENT ON COLUMN "agents"."aic" IS '智能体身份码(AIC)，符合GB/Z 185.2 OID格式，仅互联模式下有值';
COMMENT ON COLUMN "agents"."identity_status" IS 'AIP身份状态：none-未注册(本地模式默认)，active-已激活，locked-已锁定，revoked-已注销';
COMMENT ON COLUMN "agents"."aip_registered_at" IS 'AIP身份注册时间';
COMMENT ON COLUMN "agents"."capabilities" IS '辅助功能描述(ACS)，符合GB/Z 185.4，JSON格式';
COMMENT ON COLUMN "agents"."default_input_types" IS '默认输入类型(ACS)，符合GB/Z 185.4，JSON数组格式';
COMMENT ON COLUMN "agents"."default_output_types" IS '默认输出类型(ACS)，符合GB/Z 185.4，JSON数组格式';
