CREATE TABLE IF NOT EXISTS "commit" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "hash" varchar(40) NOT NULL,
  "repository_id" uuid NOT NULL,
  "branch_id" uuid NOT NULL,
  "author_id" uuid NOT NULL,
  "message" text,
  "parent_commit_ids" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "diff" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "verified" boolean NOT NULL DEFAULT false,
  "committed_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "commit" IS '代码提交记录：含哈希/差异/验证标识/父提交链。';
COMMENT ON COLUMN "commit"."id" IS '主键UUID。';
COMMENT ON COLUMN "commit"."hash" IS '提交哈希SHA-1。';
COMMENT ON COLUMN "commit"."repository_id" IS '所属仓库ID，关联repository.id。';
COMMENT ON COLUMN "commit"."branch_id" IS '所属分支ID，关联branch.id。';
COMMENT ON COLUMN "commit"."author_id" IS '作者ID，关联uctoo_user.id。';
COMMENT ON COLUMN "commit"."message" IS '提交信息。';
COMMENT ON COLUMN "commit"."parent_commit_ids" IS '父提交ID列表。';
COMMENT ON COLUMN "commit"."diff" IS '文件级变更差异。';
COMMENT ON COLUMN "commit"."verified" IS '验证标识。';
COMMENT ON COLUMN "commit"."committed_at" IS '提交时间。';
COMMENT ON COLUMN "commit"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "commit"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "commit"."created_at" IS '创建时间。';
COMMENT ON COLUMN "commit"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "commit"."deleted_at" IS '软删除时间。';
CREATE UNIQUE INDEX "uq_commit_hash" ON "commit" ("hash", "repository_id");
CREATE INDEX "idx_commit_author" ON "commit" ("author_id");
CREATE INDEX "idx_commit_branch" ON "commit" ("branch_id");

