COMMENT ON COLUMN "company"."points_balance" IS '积分余额（可用）';

CREATE TABLE IF NOT EXISTS "component_setting" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "table_catalog" text NOT NULL,
  "table_schema" text,
  "table_name" text NOT NULL,
  "page_name" text,
  "component_name" text,
  "route" text,
  "selected_table_column" text,
  "selected_form_column" text,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "component_setting" IS '组件配置';
COMMENT ON COLUMN "component_setting"."id" IS 'id';
COMMENT ON COLUMN "component_setting"."table_catalog" IS '表分组。即数据库名';
COMMENT ON COLUMN "component_setting"."table_schema" IS 'table_schema';
COMMENT ON COLUMN "component_setting"."table_name" IS '表名';
COMMENT ON COLUMN "component_setting"."page_name" IS '页面名';
COMMENT ON COLUMN "component_setting"."component_name" IS '组件名';
COMMENT ON COLUMN "component_setting"."route" IS '路由';
COMMENT ON COLUMN "component_setting"."selected_table_column" IS '已选的表列';
COMMENT ON COLUMN "component_setting"."selected_form_column" IS '已选的表单列';
COMMENT ON COLUMN "component_setting"."creator" IS '创建人';
COMMENT ON COLUMN "component_setting"."created_at" IS '创建时间';
COMMENT ON COLUMN "component_setting"."updated_at" IS '更新时间';
COMMENT ON COLUMN "component_setting"."deleted_at" IS '删除时间';

CREATE TABLE IF NOT EXISTS "composition_executions" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "composition_id" uuid NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'running'::character varying,
  "step_results" jsonb,
  "final_output" jsonb,
  "cache_hits" integer NOT NULL DEFAULT 0,
  "duration_ms" integer,
  "creator" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "completed_at" timestamptz DEFAULT NULL::timestamp with time zone,
  "deleted_at" timestamptz DEFAULT NULL::timestamp with time zone,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "composition_executions" IS '技能组合执行记录表。存储组合的每次执行情况。';
COMMENT ON COLUMN "composition_executions"."id" IS '执行记录唯一标识';
COMMENT ON COLUMN "composition_executions"."composition_id" IS '关联skill_compositions表id';
COMMENT ON COLUMN "composition_executions"."status" IS '执行状态：running/completed/failed';
COMMENT ON COLUMN "composition_executions"."step_results" IS '各步骤执行结果(JSONB)';
COMMENT ON COLUMN "composition_executions"."final_output" IS '最终输出(JSONB)';
COMMENT ON COLUMN "composition_executions"."cache_hits" IS '缓存命中次数';
COMMENT ON COLUMN "composition_executions"."duration_ms" IS '总执行耗时(毫秒)';
COMMENT ON COLUMN "composition_executions"."creator" IS '创建人';
COMMENT ON COLUMN "composition_executions"."created_at" IS '创建时间';
COMMENT ON COLUMN "composition_executions"."updated_at" IS '更新时间';
COMMENT ON COLUMN "composition_executions"."completed_at" IS '完成时间';
COMMENT ON COLUMN "composition_executions"."deleted_at" IS '删除时间';
CREATE INDEX "idx_executions_composition" ON "composition_executions" ("composition_id");
CREATE INDEX "idx_executions_status" ON "composition_executions" ("status");

CREATE TABLE IF NOT EXISTS "config" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "name" text NOT NULL,
  "parent_id" uuid,
  "component" text NOT NULL,
  "key" text NOT NULL,
  "value" text,
  "status" integer NOT NULL DEFAULT 1,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "env_key" text,
  "config_group" text DEFAULT 'other'::character varying,
  "config_type" text DEFAULT 'string'::character varying,
  "is_sensitive" boolean DEFAULT false,
  "default_value" text,
  "validation_rule" text,
  "description" text,
  "display_order" integer DEFAULT 0,
  "editable" boolean DEFAULT true,
  "last_synced_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "config" IS '配置信息';
COMMENT ON COLUMN "config"."name" IS '配置名称';
COMMENT ON COLUMN "config"."parent_id" IS '父级配置';
COMMENT ON COLUMN "config"."component" IS 'tab 引入的组件名称';
COMMENT ON COLUMN "config"."key" IS '配置键名';
COMMENT ON COLUMN "config"."value" IS '配置键值';
COMMENT ON COLUMN "config"."status" IS '状态。1 启用 0 禁用';
COMMENT ON COLUMN "config"."creator" IS '创建人';
COMMENT ON COLUMN "config"."created_at" IS '创建时间';
COMMENT ON COLUMN "config"."updated_at" IS '更新时间';
COMMENT ON COLUMN "config"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "config"."env_key" IS '对应.env文件中的键名，唯一约束';
COMMENT ON COLUMN "config"."config_group" IS '配置分组标识：logging/environment/database/ssl/model/api_key/skill/mail/storage/token/other';
COMMENT ON COLUMN "config"."config_type" IS '配置项类型：string/int/bool/url/password/path/json';
COMMENT ON COLUMN "config"."is_sensitive" IS '是否为敏感配置项（脱敏显示）';
COMMENT ON COLUMN "config"."default_value" IS '配置项默认值';
COMMENT ON COLUMN "config"."validation_rule" IS '验证规则描述，如 port:1-65535、url、bool:true|false';
COMMENT ON COLUMN "config"."description" IS '配置项中文描述说明';
COMMENT ON COLUMN "config"."display_order" IS '在分组内的显示排序，数值越小越靠前';
COMMENT ON COLUMN "config"."editable" IS '是否允许通过界面编辑';
COMMENT ON COLUMN "config"."last_synced_at" IS 'config表与.env文件最后一致的时间';
CREATE UNIQUE INDEX "idx_config_env_key" ON "config" ("env_key");
CREATE INDEX "idx_config_group" ON "config" ("config_group");

