CREATE TABLE IF NOT EXISTS "crm_business_card" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "uid" uuid NOT NULL,
  "umodel" text NOT NULL,
  "realname" text NOT NULL,
  "gender" text,
  "cover" text,
  "job_title" text,
  "sub_title" text,
  "organization" text,
  "org_logo" text,
  "mobile" text,
  "wechat" text,
  "address" text,
  "email" text,
  "attrs" text,
  "nanoid" text NOT NULL,
  "phone" text,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "crm_business_card" IS '名片信息';
COMMENT ON COLUMN "crm_business_card"."uid" IS '关联各用户表的id';
COMMENT ON COLUMN "crm_business_card"."umodel" IS '关联模型名';
COMMENT ON COLUMN "crm_business_card"."realname" IS '真实名字';
COMMENT ON COLUMN "crm_business_card"."gender" IS '性别';
COMMENT ON COLUMN "crm_business_card"."cover" IS '封面图片';
COMMENT ON COLUMN "crm_business_card"."job_title" IS '职位';
COMMENT ON COLUMN "crm_business_card"."sub_title" IS '副职位';
COMMENT ON COLUMN "crm_business_card"."organization" IS '企业组织名称';
COMMENT ON COLUMN "crm_business_card"."org_logo" IS '企业组织logo';
COMMENT ON COLUMN "crm_business_card"."mobile" IS '移动电话号码';
COMMENT ON COLUMN "crm_business_card"."wechat" IS '微信号';
COMMENT ON COLUMN "crm_business_card"."address" IS '地址';
COMMENT ON COLUMN "crm_business_card"."email" IS '邮箱';
COMMENT ON COLUMN "crm_business_card"."attrs" IS '更多字段';
COMMENT ON COLUMN "crm_business_card"."nanoid" IS '页面nanoid';
COMMENT ON COLUMN "crm_business_card"."phone" IS '固定电话号码';
COMMENT ON COLUMN "crm_business_card"."creator" IS '创建人';
COMMENT ON COLUMN "crm_business_card"."created_at" IS '创建时间';
COMMENT ON COLUMN "crm_business_card"."updated_at" IS '更新时间';
COMMENT ON COLUMN "crm_business_card"."deleted_at" IS '删除时间';

CREATE TABLE IF NOT EXISTS "crm_card_holder" (
