COMMENT ON COLUMN "crm_card_holder"."holder_uid" IS '名片夹所有者uid';
COMMENT ON COLUMN "crm_card_holder"."holder_umodel" IS '名片夹所有者umodel';
COMMENT ON COLUMN "crm_card_holder"."card_uid" IS '名片uid';
COMMENT ON COLUMN "crm_card_holder"."card_umodel" IS '名片umodel';
COMMENT ON COLUMN "crm_card_holder"."nanoid" IS '名片nanoid';
COMMENT ON COLUMN "crm_card_holder"."weight" IS '排序';
COMMENT ON COLUMN "crm_card_holder"."status" IS '状态:1=展示;0=隐藏';
COMMENT ON COLUMN "crm_card_holder"."creator" IS '创建人';
COMMENT ON COLUMN "crm_card_holder"."created_at" IS '创建时间';
COMMENT ON COLUMN "crm_card_holder"."updated_at" IS '更新时间';
COMMENT ON COLUMN "crm_card_holder"."deleted_at" IS '删除时间';

