COMMENT ON COLUMN "crm_visit_log"."from_uid" IS '来访者uid';
COMMENT ON COLUMN "crm_visit_log"."from_umodel" IS '来访者模型';
COMMENT ON COLUMN "crm_visit_log"."to_uid" IS '受访者uid';
COMMENT ON COLUMN "crm_visit_log"."to_umodel" IS '受访者模型';
