CREATE TABLE IF NOT EXISTS "crontab" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "name" text NOT NULL,
  "group_name" text NOT NULL DEFAULT 1,
  "task" text NOT NULL,
  "cron" text NOT NULL,
  "tactics" text NOT NULL,
  "remark" text NOT NULL,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "status" integer NOT NULL DEFAULT 1,
  "timeout" integer DEFAULT 0,
  "max_retries" integer DEFAULT 0,
  "retry_count" integer DEFAULT 0,
  "concurrentable" boolean DEFAULT false,
  "once" boolean DEFAULT false,
  "priority" integer DEFAULT 0,
  "parameters" text DEFAULT '{}'::text,
  "misfire_threshold" integer DEFAULT 0,
  "last_executed_at" timestamptz,
  "next_executed_at" timestamptz,
  "exec_count" integer DEFAULT 0,
  "owner_user_id" uuid,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "crontab" IS '计划任务';
COMMENT ON COLUMN "crontab"."name" IS '任务名称';
COMMENT ON COLUMN "crontab"."group_name" IS '分组。1 默认 2 系统';
COMMENT ON COLUMN "crontab"."task" IS '任务名称';
COMMENT ON COLUMN "crontab"."cron" IS 'cron 表达式';
COMMENT ON COLUMN "crontab"."tactics" IS '策略。1 立即执行 2 执行一次 3 放弃执行';
COMMENT ON COLUMN "crontab"."remark" IS '备注';
COMMENT ON COLUMN "crontab"."creator" IS '创建人';
COMMENT ON COLUMN "crontab"."created_at" IS '创建时间';
COMMENT ON COLUMN "crontab"."updated_at" IS '更新时间';
COMMENT ON COLUMN "crontab"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "crontab"."status" IS '状态。1 正常 2 禁用';
COMMENT ON COLUMN "crontab"."timeout" IS '执行超时时间(秒)。0表示不限制';
COMMENT ON COLUMN "crontab"."max_retries" IS '最大重试次数。0表示不重试';
COMMENT ON COLUMN "crontab"."retry_count" IS '当前重试计数。系统自动维护';
COMMENT ON COLUMN "crontab"."concurrentable" IS '是否允许并发执行';
COMMENT ON COLUMN "crontab"."once" IS '是否为一次性任务';
COMMENT ON COLUMN "crontab"."priority" IS '任务优先级。数值越大优先级越高';
COMMENT ON COLUMN "crontab"."parameters" IS '任务执行参数(JSON格式)';
COMMENT ON COLUMN "crontab"."misfire_threshold" IS '错过执行阈值(秒)。0表示不限制';
COMMENT ON COLUMN "crontab"."last_executed_at" IS '上次执行时间';
COMMENT ON COLUMN "crontab"."next_executed_at" IS '下次预计执行时间';
COMMENT ON COLUMN "crontab"."exec_count" IS '累计执行次数';
COMMENT ON COLUMN "crontab"."owner_user_id" IS '归属者（委派该任务的真人用户 uctoo_user.id）。与 creator 区分：creator 记执行者（可能是 agent 帐号），本列恒记归属真人；历史行允许 NULL。';
CREATE INDEX "idx_crontab_group" ON "crontab" ("group_name");
CREATE INDEX "idx_crontab_next_exec" ON "crontab" ("next_executed_at");
CREATE INDEX "idx_crontab_owner_user_id" ON "crontab" ("owner_user_id");
CREATE INDEX "idx_crontab_status" ON "crontab" ("status");

CREATE TABLE IF NOT EXISTS "crontab_log" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "crontab_id" uuid NOT NULL,
  "used_time" integer NOT NULL DEFAULT 0,
  "error_message" text NOT NULL,
  "status" integer NOT NULL DEFAULT 1,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "start_time" timestamptz,
  "end_time" timestamptz,
  "trigger_type" varchar(20) DEFAULT 'cron'::character varying,
  "retry_attempt" integer DEFAULT 0,
  "executor_type" varchar(20) DEFAULT 'unknown'::character varying,
  "result_summary" text DEFAULT ''::text,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "crontab_log" IS '计划任务记录';
COMMENT ON COLUMN "crontab_log"."crontab_id" IS 'crontab 任务ID';
COMMENT ON COLUMN "crontab_log"."used_time" IS '任务消耗时间';
COMMENT ON COLUMN "crontab_log"."error_message" IS '错误信息';
COMMENT ON COLUMN "crontab_log"."status" IS '状态。1 成功 0 失败';
COMMENT ON COLUMN "crontab_log"."creator" IS '创建人';
COMMENT ON COLUMN "crontab_log"."created_at" IS '创建时间';
COMMENT ON COLUMN "crontab_log"."updated_at" IS '更新时间';
COMMENT ON COLUMN "crontab_log"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "crontab_log"."start_time" IS '执行开始时间';
COMMENT ON COLUMN "crontab_log"."end_time" IS '执行结束时间';
COMMENT ON COLUMN "crontab_log"."trigger_type" IS '触发类型。cron:定时触发 manual:手动触发 misfire:错过执行 retry:重试 skipped_concurrent:并发跳过';
COMMENT ON COLUMN "crontab_log"."retry_attempt" IS '重试序号。0表示首次执行';
COMMENT ON COLUMN "crontab_log"."executor_type" IS '执行器类型: script/http/builtin/agent_execution/lrt/quota_reset/evaluation/skill-curator';
COMMENT ON COLUMN "crontab_log"."result_summary" IS '执行结果摘要';
CREATE INDEX "idx_crontab_log_crontab_id" ON "crontab_log" ("crontab_id");
CREATE INDEX "idx_crontab_log_start_time" ON "crontab_log" ("start_time");
CREATE INDEX "idx_crontab_log_trigger_type" ON "crontab_log" ("trigger_type");

CREATE TABLE IF NOT EXISTS "crontab_task_registry" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "type" varchar(20) NOT NULL,
  "prefix" varchar(50) NOT NULL,
  "name" varchar(100) NOT NULL,
  "description" text DEFAULT ''::text,
  "parameters_template" text DEFAULT '{}'::text,
  "status" integer DEFAULT 1,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "crontab_task_registry" IS '任务执行器注册表';
COMMENT ON COLUMN "crontab_task_registry"."type" IS '执行器类型: script/http/builtin/agent_execution/lrt/quota_reset/evaluation/skill-curator';
COMMENT ON COLUMN "crontab_task_registry"."prefix" IS '标识前缀: script://, http://, https://, builtin://';
COMMENT ON COLUMN "crontab_task_registry"."name" IS '执行器名称（唯一）';
COMMENT ON COLUMN "crontab_task_registry"."description" IS '执行器描述';
COMMENT ON COLUMN "crontab_task_registry"."parameters_template" IS '参数模板(JSON格式)';
COMMENT ON COLUMN "crontab_task_registry"."status" IS '状态。1 启用 2 禁用';
COMMENT ON COLUMN "crontab_task_registry"."creator" IS '注册者';
COMMENT ON COLUMN "crontab_task_registry"."created_at" IS '创建时间';
COMMENT ON COLUMN "crontab_task_registry"."updated_at" IS '更新时间';
COMMENT ON COLUMN "crontab_task_registry"."deleted_at" IS '删除时间（软删除）';
CREATE UNIQUE INDEX "crontab_task_registry_name_key" ON "crontab_task_registry" ("name");
CREATE UNIQUE INDEX "crontab_task_registry_prefix_key" ON "crontab_task_registry" ("prefix");
CREATE INDEX "idx_crontab_task_registry_status" ON "crontab_task_registry" ("status");
CREATE INDEX "idx_crontab_task_registry_type" ON "crontab_task_registry" ("type");

