CREATE TABLE IF NOT EXISTS "data_access_authorization" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "entity_id" text NOT NULL,
  "entity_type" varchar(50) NOT NULL,
  "user_id" uuid NOT NULL,
  "permission" integer NOT NULL,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "data_access_authorization" IS '数据访问授权';
COMMENT ON COLUMN "data_access_authorization"."id" IS 'id';
COMMENT ON COLUMN "data_access_authorization"."entity_id" IS '实体id';
COMMENT ON COLUMN "data_access_authorization"."entity_type" IS '实体类型';
