COMMENT ON COLUMN "data_access_authorization"."creator" IS '创建人';
COMMENT ON COLUMN "data_access_authorization"."created_at" IS '创建时间';
COMMENT ON COLUMN "data_access_authorization"."updated_at" IS '更新时间';
COMMENT ON COLUMN "data_access_authorization"."deleted_at" IS '删除时间';
CREATE INDEX "data_access_authorization_entity_id_entity_type_user_id_idx" ON "data_access_authorization" ("entity_id", "entity_type", "user_id");

CREATE TABLE IF NOT EXISTS "db_connection" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "user" text NOT NULL,
  "password" text NOT NULL,
  "host" text NOT NULL,
  "port" text NOT NULL,
  "database_name" text NOT NULL,
  "ssl" integer NOT NULL DEFAULT 0,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "provider" text NOT NULL,
  "type" text DEFAULT ''::character varying,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "db_connection" IS '数据库连接';
COMMENT ON COLUMN "db_connection"."id" IS 'id';
COMMENT ON COLUMN "db_connection"."user" IS '用户名';
COMMENT ON COLUMN "db_connection"."password" IS '密码';
COMMENT ON COLUMN "db_connection"."host" IS '主机地址';
COMMENT ON COLUMN "db_connection"."port" IS '端口';
COMMENT ON COLUMN "db_connection"."database_name" IS '数据库名';
COMMENT ON COLUMN "db_connection"."ssl" IS '是否ssl，0=否，1=是';
COMMENT ON COLUMN "db_connection"."creator" IS '创建人';
COMMENT ON COLUMN "db_connection"."created_at" IS '创建时间';
COMMENT ON COLUMN "db_connection"."updated_at" IS '更新时间';
COMMENT ON COLUMN "db_connection"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "db_connection"."provider" IS '数据库驱动，postgresql、mysql等';
COMMENT ON COLUMN "db_connection"."type" IS '类型，uctoo等';

CREATE TABLE IF NOT EXISTS "db_info" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "table_catalog" text NOT NULL,
  "table_schema" text,
  "table_name" text NOT NULL,
  "column_name" text NOT NULL,
  "column_default" text,
  "is_nullable" text NOT NULL DEFAULT 'YES'::character varying,
  "data_type" text,
  "vue_component_type" text DEFAULT 'textarea'::character varying,
  "react_component_type" text DEFAULT 'textarea'::character varying,
  "arkui_component_type" text DEFAULT 'TextArea'::character varying,
  "uniapp_component_type" text DEFAULT 'textarea'::character varying,
  "rules" text,
  "pattern" text,
  "weight" integer NOT NULL DEFAULT 0,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "placeholder" text,
  "is_column_hidden" text NOT NULL DEFAULT 'NO'::character varying,
  "is_table_hidden" text NOT NULL DEFAULT 'NO'::character varying,
  "column_comment" text,
  "ordinal_position" integer NOT NULL DEFAULT 0,
  "migration_id" text DEFAULT 'dev'::character varying,
  "character_maximum_length" bigint DEFAULT 11,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "db_info" IS '数据库信息。屏蔽不同数据库差异，保存一致的数据库结构信息，便于可视化代码生成。可用于codelabs表的数据源data_source';
COMMENT ON COLUMN "db_info"."id" IS 'id';
COMMENT ON COLUMN "db_info"."table_catalog" IS '表分组。即数据库名';
COMMENT ON COLUMN "db_info"."table_schema" IS 'table_schema';
COMMENT ON COLUMN "db_info"."table_name" IS '表名';
COMMENT ON COLUMN "db_info"."column_name" IS '列名';
COMMENT ON COLUMN "db_info"."column_default" IS '默认值';
COMMENT ON COLUMN "db_info"."is_nullable" IS '是否可空。YES可空，NO不可空。';
COMMENT ON COLUMN "db_info"."data_type" IS '数据类型';
COMMENT ON COLUMN "db_info"."vue_component_type" IS 'vue控件类型。一般用于生成PC端管理后台代码。';
COMMENT ON COLUMN "db_info"."react_component_type" IS 'vue控件类型。一般用于生成PC端管理后台代码。';
COMMENT ON COLUMN "db_info"."arkui_component_type" IS 'arkui控件类型。一般用于生成鸿蒙原生应用代码。';
COMMENT ON COLUMN "db_info"."uniapp_component_type" IS 'uniapp控件类型。一般用于生成小程序应用代码。';
COMMENT ON COLUMN "db_info"."rules" IS '校验规则';
COMMENT ON COLUMN "db_info"."pattern" IS '正则表达式';
COMMENT ON COLUMN "db_info"."weight" IS '排序';
COMMENT ON COLUMN "db_info"."creator" IS '创建人';
COMMENT ON COLUMN "db_info"."created_at" IS '创建时间';
COMMENT ON COLUMN "db_info"."updated_at" IS '更新时间';
COMMENT ON COLUMN "db_info"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "db_info"."placeholder" IS '占位符或tips';
COMMENT ON COLUMN "db_info"."is_column_hidden" IS '字段是否隐藏。YES=隐藏，NO=显示。';
COMMENT ON COLUMN "db_info"."is_table_hidden" IS '表是否隐藏。YES=隐藏，NO=显示。由于是字段表，因此这个字段存在冗余，应保持同一个表在多条字段记录中此值一致。';
COMMENT ON COLUMN "db_info"."column_comment" IS '列备注';
COMMENT ON COLUMN "db_info"."ordinal_position" IS '列的顺序位置';
COMMENT ON COLUMN "db_info"."migration_id" IS '关联_prisma_migrations表id。可作为数据库版本管理标识。';

CREATE TABLE IF NOT EXISTS "departments" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "department_name" text NOT NULL,
  "parent_id" uuid,
  "principal" text,
