  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "departments" IS '部门信息';
COMMENT ON COLUMN "departments"."department_name" IS '部门名称';
COMMENT ON COLUMN "departments"."parent_id" IS '父级ID';
COMMENT ON COLUMN "departments"."principal" IS '负责人';
COMMENT ON COLUMN "departments"."mobile" IS '联系电话';
