CREATE TABLE IF NOT EXISTS "event_handlers" (
  "id" varchar(36) NOT NULL DEFAULT gen_random_uuid(),
  "event_type" varchar(50) NOT NULL,
  "handler_name" varchar(200) NOT NULL,
  "handler_class" varchar(500) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'active'::character varying,
  "config" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "description" text,
  "creator" varchar(36),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "event_handlers" IS '事件处理器注册表';
COMMENT ON COLUMN "event_handlers"."event_type" IS '事件类型(13种：ToolCallStart/End/Repeat/ChatModelStart/End/Failure/AgentStart/End/Step/SubAgentStart/End/Timeout/UserInput/Notify)';
COMMENT ON COLUMN "event_handlers"."handler_class" IS '处理器类全限定名';
CREATE UNIQUE INDEX "idx_event_handlers_unique" ON "event_handlers" ("event_type", "handler_name");
CREATE INDEX "idx_event_handlers_type" ON "event_handlers" ("event_type");

CREATE TABLE IF NOT EXISTS "execution_evidences" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "agent_id" uuid NOT NULL,
  "session_id" varchar(100) NOT NULL,
  "step_id" varchar(100) NOT NULL,
  "parent_step_id" varchar(100),
  "step_type" varchar(20) NOT NULL,
  "input" jsonb NOT NULL,
  "output" jsonb,
  "duration_ms" bigint,
  "side_effects" jsonb,
  "hash" varchar(64) NOT NULL,
  "creator" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz DEFAULT NULL::timestamp with time zone,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "execution_evidences" IS '执行证据表。记录Agent执行的每个步骤的完整证据链。';
COMMENT ON COLUMN "execution_evidences"."id" IS '证据唯一标识';
COMMENT ON COLUMN "execution_evidences"."agent_id" IS '关联agents表id';
COMMENT ON COLUMN "execution_evidences"."session_id" IS '执行会话ID';
COMMENT ON COLUMN "execution_evidences"."step_id" IS '步骤ID';
COMMENT ON COLUMN "execution_evidences"."parent_step_id" IS '父步骤ID';
COMMENT ON COLUMN "execution_evidences"."step_type" IS '步骤类型：decision/tool_call/task_transfer';
COMMENT ON COLUMN "execution_evidences"."input" IS '步骤输入(JSONB)';
COMMENT ON COLUMN "execution_evidences"."output" IS '步骤输出(JSONB)';
COMMENT ON COLUMN "execution_evidences"."duration_ms" IS '执行耗时(毫秒)';
COMMENT ON COLUMN "execution_evidences"."side_effects" IS '副作用记录(JSONB)';
COMMENT ON COLUMN "execution_evidences"."hash" IS '哈希链校验值(SHA-256)';
COMMENT ON COLUMN "execution_evidences"."creator" IS '创建人';
COMMENT ON COLUMN "execution_evidences"."created_at" IS '创建时间';
COMMENT ON COLUMN "execution_evidences"."updated_at" IS '更新时间';
COMMENT ON COLUMN "execution_evidences"."deleted_at" IS '删除时间';
CREATE INDEX "idx_evidences_agent" ON "execution_evidences" ("agent_id");
CREATE INDEX "idx_evidences_hash" ON "execution_evidences" ("hash");
CREATE INDEX "idx_evidences_session" ON "execution_evidences" ("session_id");
CREATE INDEX "idx_evidences_step" ON "execution_evidences" ("step_id");

CREATE TABLE IF NOT EXISTS "faq" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "title" text NOT NULL,
  "content" text NOT NULL,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "faq" IS '常见问题';
COMMENT ON COLUMN "faq"."title" IS '标题';
COMMENT ON COLUMN "faq"."content" IS '内容';
COMMENT ON COLUMN "faq"."creator" IS '创建人';
COMMENT ON COLUMN "faq"."created_at" IS '创建时间';
COMMENT ON COLUMN "faq"."updated_at" IS '更新时间';
COMMENT ON COLUMN "faq"."deleted_at" IS '删除时间';

CREATE TABLE IF NOT EXISTS "feedback" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "user_id" uuid NOT NULL,
  "type" text,
  "content" text,
  "images" text,
  "phone" text,
  "remark" text,
  "status" integer NOT NULL DEFAULT 0,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "feedback" IS '反馈信息';
COMMENT ON COLUMN "feedback"."user_id" IS '用户id';
COMMENT ON COLUMN "feedback"."type" IS '反馈类型';
COMMENT ON COLUMN "feedback"."content" IS '反馈内容';
COMMENT ON COLUMN "feedback"."images" IS '图片';
COMMENT ON COLUMN "feedback"."phone" IS '联系电话';
COMMENT ON COLUMN "feedback"."remark" IS '处理备注';
COMMENT ON COLUMN "feedback"."status" IS '是否处理。0=未处理,1=已处理';
COMMENT ON COLUMN "feedback"."creator" IS '创建人';
COMMENT ON COLUMN "feedback"."created_at" IS '创建时间';
COMMENT ON COLUMN "feedback"."updated_at" IS '更新时间';
COMMENT ON COLUMN "feedback"."deleted_at" IS '删除时间';

CREATE TABLE IF NOT EXISTS "group_has_permission" (
  "group_id" uuid NOT NULL,
  "permission_name" text NOT NULL,
  "status" integer NOT NULL DEFAULT 0,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("group_id", "permission_name")
);
COMMENT ON TABLE "group_has_permission" IS '用户组权限';
COMMENT ON COLUMN "group_has_permission"."group_id" IS '关联user_group.id';
COMMENT ON COLUMN "group_has_permission"."permission_name" IS '关联permissions.id';
COMMENT ON COLUMN "group_has_permission"."status" IS '状态';
COMMENT ON COLUMN "group_has_permission"."creator" IS '创建人';
COMMENT ON COLUMN "group_has_permission"."created_at" IS '创建时间';
COMMENT ON COLUMN "group_has_permission"."updated_at" IS '更新时间';
COMMENT ON COLUMN "group_has_permission"."deleted_at" IS '删除时间';

CREATE TABLE IF NOT EXISTS "group_tag" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "group_id" uuid NOT NULL,
  "tagId" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "creator" uuid,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON COLUMN "group_tag"."created_at" IS '创建时间';
COMMENT ON COLUMN "group_tag"."creator" IS '创建人';
COMMENT ON COLUMN "group_tag"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "group_tag"."updated_at" IS '更新时间';
CREATE UNIQUE INDEX "unique_tag_per_group" ON "group_tag" ("group_id", "tagId");

CREATE TABLE IF NOT EXISTS "guest_users" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "nickname" text,
  "token" text,
  "domain" text,
  "ipAddress" text,
  "userAgent" text,
  "referer" text,
  "lastAccessTime" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "mobile" text,
  "channel" text,
  "comments" text,
  "user_id" uuid,
  "user_model" text,
  "appid" text,
  "status" integer DEFAULT 0,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "guest_users" IS '匿名用户，访客信息';
COMMENT ON COLUMN "guest_users"."nickname" IS '昵称';
COMMENT ON COLUMN "guest_users"."token" IS 'token';
COMMENT ON COLUMN "guest_users"."domain" IS '来源域名';
COMMENT ON COLUMN "guest_users"."ipAddress" IS 'ip地址';
COMMENT ON COLUMN "guest_users"."userAgent" IS '用户端类型';
COMMENT ON COLUMN "guest_users"."referer" IS '来源网址';
COMMENT ON COLUMN "guest_users"."lastAccessTime" IS '最近访问时间';
COMMENT ON COLUMN "guest_users"."mobile" IS '手机号码';
COMMENT ON COLUMN "guest_users"."channel" IS '来源渠道';
COMMENT ON COLUMN "guest_users"."comments" IS '备注';
COMMENT ON COLUMN "guest_users"."user_id" IS '关联用户id';
COMMENT ON COLUMN "guest_users"."user_model" IS '关联用户模型';
COMMENT ON COLUMN "guest_users"."appid" IS 'appid';
COMMENT ON COLUMN "guest_users"."status" IS '状态';
COMMENT ON COLUMN "guest_users"."creator" IS '创建人';
COMMENT ON COLUMN "guest_users"."created_at" IS '创建时间';
COMMENT ON COLUMN "guest_users"."updated_at" IS '更新时间';
COMMENT ON COLUMN "guest_users"."deleted_at" IS '删除时间';

CREATE TABLE IF NOT EXISTS "i18" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "key" text NOT NULL,
  "content" text NOT NULL,
  "lang_id" uuid,
  "creator" uuid,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "i18" IS '国际化内容';
COMMENT ON COLUMN "i18"."id" IS '主键UUID';
COMMENT ON COLUMN "i18"."key" IS '国际化key';
COMMENT ON COLUMN "i18"."content" IS '内容';
COMMENT ON COLUMN "i18"."lang_id" IS '语言ID';

