CREATE TABLE IF NOT EXISTS "issue_comment" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "task_id" uuid NOT NULL,
  "commenter_id" uuid NOT NULL,
  "content" text,
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "issue_comment" IS 'Issue评论：关联tasks表。';
COMMENT ON COLUMN "issue_comment"."id" IS '主键UUID。';
COMMENT ON COLUMN "issue_comment"."task_id" IS '关联tasks.id（Issue）。';
COMMENT ON COLUMN "issue_comment"."commenter_id" IS '评论者ID，关联uctoo_user.id。';
COMMENT ON COLUMN "issue_comment"."content" IS '评论内容。';
COMMENT ON COLUMN "issue_comment"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "issue_comment"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "issue_comment"."created_at" IS '创建时间。';
COMMENT ON COLUMN "issue_comment"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "issue_comment"."deleted_at" IS '软删除时间。';
CREATE INDEX "idx_issue_comment_task" ON "issue_comment" ("task_id");

CREATE TABLE IF NOT EXISTS "jobs" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "job_name" text NOT NULL,
  "coding" text NOT NULL,
  "description" text NOT NULL,
  "weight" integer NOT NULL DEFAULT 0,
  "status" integer NOT NULL DEFAULT 1,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "jobs" IS '岗位信息';
COMMENT ON COLUMN "jobs"."job_name" IS '岗位名称';
COMMENT ON COLUMN "jobs"."coding" IS '编码';
COMMENT ON COLUMN "jobs"."description" IS '描述';
COMMENT ON COLUMN "jobs"."weight" IS '排序';
COMMENT ON COLUMN "jobs"."status" IS '1 正常 0 停用';
COMMENT ON COLUMN "jobs"."creator" IS '创建人';
COMMENT ON COLUMN "jobs"."created_at" IS '创建时间';
COMMENT ON COLUMN "jobs"."updated_at" IS '更新时间';
COMMENT ON COLUMN "jobs"."deleted_at" IS '删除时间';

CREATE TABLE IF NOT EXISTS "label" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "name" varchar(64) NOT NULL,
  "color" varchar(7) NOT NULL DEFAULT '#6366f1'::character varying,
  "description" varchar(256),
  "repository_id" uuid NOT NULL,
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "label" IS '仓库标签。';
COMMENT ON COLUMN "label"."id" IS '主键UUID。';
COMMENT ON COLUMN "label"."name" IS '标签名。';
COMMENT ON COLUMN "label"."color" IS '十六进制颜色。';
COMMENT ON COLUMN "label"."description" IS '标签描述。';
COMMENT ON COLUMN "label"."repository_id" IS '所属仓库ID，关联repository.id。';
COMMENT ON COLUMN "label"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "label"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "label"."created_at" IS '创建时间。';
COMMENT ON COLUMN "label"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "label"."deleted_at" IS '软删除时间。';
CREATE UNIQUE INDEX "uq_label_repo_name" ON "label" ("name", "repository_id");

CREATE TABLE IF NOT EXISTS "lang" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "name" text NOT NULL,
  "code" text NOT NULL,
  "status" integer NOT NULL DEFAULT 1,
  "creator" uuid,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "lang" IS '语言管理';
COMMENT ON COLUMN "lang"."id" IS '主键UUID';
COMMENT ON COLUMN "lang"."name" IS '语言名称';
COMMENT ON COLUMN "lang"."code" IS '语言代码';
COMMENT ON COLUMN "lang"."status" IS '状态';

