CREATE TABLE IF NOT EXISTS "link" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "link" text NOT NULL,
  "privacy_cevel" integer NOT NULL DEFAULT 0,
  "owner" uuid,
  "stars" double precision NOT NULL DEFAULT 0,
  "description" text,
  "group_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "creator" uuid,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "link" IS '链接信息';
COMMENT ON COLUMN "link"."link" IS '链接url';
COMMENT ON COLUMN "link"."privacy_cevel" IS '隐私等级';
COMMENT ON COLUMN "link"."owner" IS '所有者。关联user表username';
COMMENT ON COLUMN "link"."stars" IS '星级';
COMMENT ON COLUMN "link"."description" IS '描述';
COMMENT ON COLUMN "link"."group_id" IS '分组id';
COMMENT ON COLUMN "link"."created_at" IS '创建时间';
COMMENT ON COLUMN "link"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "link"."updated_at" IS '更新时间';
COMMENT ON COLUMN "link"."creator" IS '创建人';
CREATE INDEX "fki_links_owner_fkey" ON "link" ("owner");

CREATE TABLE IF NOT EXISTS "link_group" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "owner" text NOT NULL,
  "groupname" text NOT NULL,
  "name" text NOT NULL,
  "description" text NOT NULL,
  "picture" text NOT NULL DEFAULT ''::character varying,
  "stars" double precision NOT NULL DEFAULT 0,
  "watcher_count" integer NOT NULL DEFAULT 0,
  "linked_count" integer NOT NULL DEFAULT 0,
  "links_count" integer NOT NULL DEFAULT 0,
  "privacy_level" integer NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "creator" uuid,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "link_group" IS '链接分组';
COMMENT ON COLUMN "link_group"."owner" IS '归属用户。关联user表username';
COMMENT ON COLUMN "link_group"."groupname" IS '分组名';
COMMENT ON COLUMN "link_group"."name" IS '组名。英文唯一描述';
COMMENT ON COLUMN "link_group"."description" IS '描述';
COMMENT ON COLUMN "link_group"."picture" IS '图片';
COMMENT ON COLUMN "link_group"."stars" IS '星级';
COMMENT ON COLUMN "link_group"."watcher_count" IS '浏览数';
COMMENT ON COLUMN "link_group"."linked_count" IS '被链接数';
COMMENT ON COLUMN "link_group"."links_count" IS '链接数量';
COMMENT ON COLUMN "link_group"."privacy_level" IS '隐私等级';
COMMENT ON COLUMN "link_group"."created_at" IS '创建时间';
COMMENT ON COLUMN "link_group"."creator" IS '创建人';
COMMENT ON COLUMN "link_group"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "link_group"."updated_at" IS '更新时间';
CREATE UNIQUE INDEX "unique_groupname_per_owner" ON "link_group" ("owner", "groupname");
CREATE INDEX "lg_owner_fkey" ON "link_group" ("owner");

CREATE TABLE IF NOT EXISTS "link_tag" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "link_id" uuid NOT NULL,
  "tag_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "creator" uuid,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "link_tag" IS '链接标签关联';
COMMENT ON COLUMN "link_tag"."link_id" IS '链接id';
COMMENT ON COLUMN "link_tag"."tag_id" IS '标签id';
COMMENT ON COLUMN "link_tag"."created_at" IS '创建时间';
COMMENT ON COLUMN "link_tag"."creator" IS '创建人';
COMMENT ON COLUMN "link_tag"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "link_tag"."updated_at" IS '更新时间';
CREATE UNIQUE INDEX "unique_tag_per_link" ON "link_tag" ("link_id", "tag_id");

CREATE TABLE IF NOT EXISTS "llm_channel" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "code" varchar(64) NOT NULL,
  "display_name" varchar(128),
  "protocol" varchar(32) NOT NULL DEFAULT 'openai-chat'::character varying,
  "base_url" varchar(512),
  "secret_ref" varchar(256),
  "default_model" varchar(128),
  "capabilities" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "scopes" jsonb NOT NULL DEFAULT '["global"]'::jsonb,
  "priority" integer NOT NULL DEFAULT 0,
  "status" varchar(16) NOT NULL DEFAULT 'enabled'::character varying,
  "is_default" boolean NOT NULL DEFAULT false,
  "health" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "probe_at" timestamptz,
  "config" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "revision" bigint NOT NULL DEFAULT 0,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "api_key" text
);
COMMENT ON TABLE "llm_channel" IS '大模型通道注册表：运行时通道真相源';
COMMENT ON COLUMN "llm_channel"."code" IS '通道编码，即 provider（arcbench/deepseek/ollama…），唯一';
COMMENT ON COLUMN "llm_channel"."protocol" IS 'openai-chat / openai-embedding / openai-image / plugin:<name>（L3 适配器插件）';
COMMENT ON COLUMN "llm_channel"."base_url" IS '只写到 /v1 级（沿用 SOP 约定）';
COMMENT ON COLUMN "llm_channel"."secret_ref" IS 'env:VAR / db:<id> / vault:<path>；不存明文';
COMMENT ON COLUMN "llm_channel"."capabilities" IS '通道级能力位 chat/stream/tools/vision/embedding/image/reasoning';
COMMENT ON COLUMN "llm_channel"."scopes" IS '允许的作用域，默认 ["global"]';
COMMENT ON COLUMN "llm_channel"."status" IS 'enabled / disabled / probing / degraded';
