);
COMMENT ON TABLE "minishop_order" IS '商城订单';
COMMENT ON COLUMN "minishop_order"."order_id" IS '微信侧订单id';
COMMENT ON COLUMN "minishop_order"."out_order_id" IS '商家自定义订单ID';
COMMENT ON COLUMN "minishop_order"."out_trade_no" IS '商户支付订单号';
COMMENT ON COLUMN "minishop_order"."openid" IS '微信用户openid';
COMMENT ON COLUMN "minishop_order"."user_id" IS '用户id';
COMMENT ON COLUMN "minishop_order"."type" IS '非必填，默认为0。0:普通场景, 1:合单支付';
COMMENT ON COLUMN "minishop_order"."path" IS '商家小程序该订单的页面path，用于微信侧订单中心跳转';
COMMENT ON COLUMN "minishop_order"."scene" IS '下单时小程序的场景值';
