COMMENT ON COLUMN "permissions"."redirect" IS '跳转地址';
COMMENT ON COLUMN "permissions"."type" IS '类型。1 菜单 2 按钮 3路由 4工具';
COMMENT ON COLUMN "permissions"."hidden" IS '是否隐藏。0隐藏，1显示';
COMMENT ON COLUMN "permissions"."weight" IS '排序';
COMMENT ON COLUMN "permissions"."creator" IS '创建人';
COMMENT ON COLUMN "permissions"."created_at" IS '创建时间';
COMMENT ON COLUMN "permissions"."updated_at" IS '更新时间';
COMMENT ON COLUMN "permissions"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "permissions"."keepalive" IS '1 缓存 2 不存在';
COMMENT ON COLUMN "permissions"."menu_type" IS '菜单类型';
COMMENT ON COLUMN "permissions"."locale" IS '国际化key';
CREATE UNIQUE INDEX "permissions_permission_name_key" ON "permissions" ("permission_name");

