CREATE TABLE IF NOT EXISTS "pivot_table" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "worksheet_id" uuid NOT NULL,
  "source_worksheet_id" uuid NOT NULL,
  "source_range_start" varchar(10) NOT NULL,
  "source_range_end" varchar(10) NOT NULL,
  "row_dimension" varchar(128) NOT NULL,
  "column_dimension" varchar(128) NOT NULL,
  "value_field" varchar(128) NOT NULL,
  "aggregation" varchar(20) NOT NULL DEFAULT 'SUM'::character varying,
  "result_range_start" varchar(10),
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "pivot_table" IS '透视表：行列维度+值聚合+独立结果区域。';
COMMENT ON COLUMN "pivot_table"."id" IS '主键UUID。';
COMMENT ON COLUMN "pivot_table"."worksheet_id" IS '透视表所在工作表ID，关联worksheet.id。';
COMMENT ON COLUMN "pivot_table"."source_worksheet_id" IS '源数据工作表ID，关联worksheet.id。';
COMMENT ON COLUMN "pivot_table"."source_range_start" IS '源区域起始坐标。';
COMMENT ON COLUMN "pivot_table"."source_range_end" IS '源区域结束坐标。';
COMMENT ON COLUMN "pivot_table"."row_dimension" IS '行维度字段。';
COMMENT ON COLUMN "pivot_table"."column_dimension" IS '列维度字段。';
COMMENT ON COLUMN "pivot_table"."value_field" IS '值字段。';
COMMENT ON COLUMN "pivot_table"."aggregation" IS '聚合方式：SUM/COUNT/AVERAGE。';
COMMENT ON COLUMN "pivot_table"."result_range_start" IS '结果显示区域起始坐标。';
COMMENT ON COLUMN "pivot_table"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "pivot_table"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "pivot_table"."created_at" IS '创建时间。';
COMMENT ON COLUMN "pivot_table"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "pivot_table"."deleted_at" IS '软删除时间。';
CREATE INDEX "idx_pivot_worksheet" ON "pivot_table" ("worksheet_id");

CREATE TABLE IF NOT EXISTS "point_transactions" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "account_type" varchar(20) NOT NULL,
  "account_id" uuid NOT NULL,
  "transaction_type" varchar(30) NOT NULL,
  "amount" bigint NOT NULL,
  "balance_before" bigint NOT NULL DEFAULT 0,
  "balance_after" bigint NOT NULL DEFAULT 0,
  "task_id" uuid,
  "counterparty_type" varchar(20),
  "counterparty_id" uuid,
  "description" varchar(500),
  "remark" text,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "point_transactions" IS '积分流水表';
COMMENT ON COLUMN "point_transactions"."account_type" IS '账户类型：user(用户)/company(公司)';
COMMENT ON COLUMN "point_transactions"."account_id" IS '账户ID（user类型为uctoo_user.id；company类型为company.id）';
COMMENT ON COLUMN "point_transactions"."transaction_type" IS '交易类型：recharge(充值)/freeze(冻结)/unfreeze(解冻)/settle(结算收入)/settle_pay(结算支出)/refund(退还)/adjust(调整)/bonus(奖励)/punish(扣罚)';
COMMENT ON COLUMN "point_transactions"."amount" IS '变动数量（正数为增加，负数为减少）';
COMMENT ON COLUMN "point_transactions"."balance_before" IS '变动前余额';
COMMENT ON COLUMN "point_transactions"."balance_after" IS '变动后余额';
COMMENT ON COLUMN "point_transactions"."task_id" IS '关联任务ID';
COMMENT ON COLUMN "point_transactions"."counterparty_type" IS '交易对手类型：user/company';
COMMENT ON COLUMN "point_transactions"."counterparty_id" IS '交易对手ID';
COMMENT ON COLUMN "point_transactions"."description" IS '交易描述';
COMMENT ON COLUMN "point_transactions"."remark" IS '备注';
COMMENT ON COLUMN "point_transactions"."creator" IS '创建人';
COMMENT ON COLUMN "point_transactions"."created_at" IS '创建时间';
COMMENT ON COLUMN "point_transactions"."updated_at" IS '更新时间';
COMMENT ON COLUMN "point_transactions"."deleted_at" IS '删除时间';
CREATE INDEX "idx_point_transactions_account" ON "point_transactions" ("account_type", "account_id");
CREATE INDEX "idx_point_transactions_created" ON "point_transactions" ("created_at");
CREATE INDEX "idx_point_transactions_task" ON "point_transactions" ("task_id");
CREATE INDEX "idx_point_transactions_type" ON "point_transactions" ("transaction_type");

CREATE TABLE IF NOT EXISTS "pr_review" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "pull_request_id" uuid NOT NULL,
  "reviewer_id" uuid NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'pending'::character varying,
  "content" text,
  "line_number" integer,
  "file_path" varchar(512),
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "pr_review" IS 'PR评审：Approve/Request Changes/Comment。';
COMMENT ON COLUMN "pr_review"."id" IS '主键UUID。';
COMMENT ON COLUMN "pr_review"."pull_request_id" IS '关联PR ID，关联pull_request.id。';
COMMENT ON COLUMN "pr_review"."reviewer_id" IS '评审者ID，关联uctoo_user.id。';
COMMENT ON COLUMN "pr_review"."status" IS '评审状态：pending/approved/request_changes/comment。';
COMMENT ON COLUMN "pr_review"."content" IS '评审内容。';
COMMENT ON COLUMN "pr_review"."line_number" IS '评审针对的代码行号。';
COMMENT ON COLUMN "pr_review"."file_path" IS '评审针对的文件路径。';
COMMENT ON COLUMN "pr_review"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "pr_review"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "pr_review"."created_at" IS '创建时间。';
COMMENT ON COLUMN "pr_review"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "pr_review"."deleted_at" IS '软删除时间。';
CREATE INDEX "idx_pr_review_pr" ON "pr_review" ("pull_request_id");

CREATE TABLE IF NOT EXISTS "pull_request" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "title" varchar(256) NOT NULL,
  "description" text,
  "status" varchar(20) NOT NULL DEFAULT 'open'::character varying,
  "is_draft" boolean NOT NULL DEFAULT false,
  "repository_id" uuid NOT NULL,
  "base_branch_id" uuid NOT NULL,
  "compare_branch_id" uuid NOT NULL,
  "mergeable" boolean,
  "merged_at" timestamptz,
  "merged_by_id" uuid,
  "milestone_id" uuid,
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "pull_request" IS 'PR：base/compare分支/评审/合并状态。';
COMMENT ON COLUMN "pull_request"."id" IS '主键UUID。';
COMMENT ON COLUMN "pull_request"."title" IS 'PR标题。';
COMMENT ON COLUMN "pull_request"."description" IS 'PR描述。';
COMMENT ON COLUMN "pull_request"."status" IS '状态：open/closed/merged。';
COMMENT ON COLUMN "pull_request"."is_draft" IS '是否草稿。';
COMMENT ON COLUMN "pull_request"."repository_id" IS '所属仓库ID，关联repository.id。';
COMMENT ON COLUMN "pull_request"."base_branch_id" IS '目标分支ID，关联branch.id。';
COMMENT ON COLUMN "pull_request"."compare_branch_id" IS '源分支ID，关联branch.id。';
COMMENT ON COLUMN "pull_request"."mergeable" IS '是否可合并。';
COMMENT ON COLUMN "pull_request"."merged_at" IS '合并时间。';
COMMENT ON COLUMN "pull_request"."merged_by_id" IS '合并者ID，关联uctoo_user.id。';
COMMENT ON COLUMN "pull_request"."milestone_id" IS '关联里程碑ID，关联milestone.id。';
COMMENT ON COLUMN "pull_request"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "pull_request"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "pull_request"."created_at" IS '创建时间。';
COMMENT ON COLUMN "pull_request"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "pull_request"."deleted_at" IS '软删除时间。';
CREATE INDEX "idx_pr_repository" ON "pull_request" ("repository_id");
CREATE INDEX "idx_pr_status" ON "pull_request" ("status");

CREATE TABLE IF NOT EXISTS "repository" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "name" varchar(128) NOT NULL,
  "description" varchar(350),
  "visibility" varchar(20) NOT NULL DEFAULT 'public'::character varying,
  "default_branch" varchar(128) NOT NULL DEFAULT 'main'::character varying,
  "owner_type" varchar(20) NOT NULL DEFAULT 'user'::character varying,
  "owner_id" uuid NOT NULL,
  "is_fork" boolean NOT NULL DEFAULT false,
  "forked_from_id" uuid,
  "language" varchar(64),
  "star_count" integer NOT NULL DEFAULT 0,
  "fork_count" integer NOT NULL DEFAULT 0,
  "topics" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "repository" IS 'GitHub风格仓库：name在owner_id下唯一，visibility控制可见性。';
COMMENT ON COLUMN "repository"."id" IS '主键UUID。';
COMMENT ON COLUMN "repository"."name" IS '仓库名。';
COMMENT ON COLUMN "repository"."description" IS '仓库描述。';
COMMENT ON COLUMN "repository"."visibility" IS '可见性：public/private。';
COMMENT ON COLUMN "repository"."default_branch" IS '默认分支名。';
COMMENT ON COLUMN "repository"."owner_type" IS '拥有者类型：user/organization。';
COMMENT ON COLUMN "repository"."owner_id" IS '拥有者ID，关联uctoo_user.id或company.id。';
COMMENT ON COLUMN "repository"."is_fork" IS '是否Fork仓库。';
COMMENT ON COLUMN "repository"."forked_from_id" IS '源仓库ID（Fork时填）。';
COMMENT ON COLUMN "repository"."language" IS '主语言。';
COMMENT ON COLUMN "repository"."star_count" IS '星标数。';
COMMENT ON COLUMN "repository"."fork_count" IS 'Fork数。';
COMMENT ON COLUMN "repository"."topics" IS '话题标签列表。';
COMMENT ON COLUMN "repository"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "repository"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "repository"."created_at" IS '创建时间。';
COMMENT ON COLUMN "repository"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "repository"."deleted_at" IS '软删除时间。';
CREATE UNIQUE INDEX "uq_repository_owner_name" ON "repository" ("name", "owner_id");
CREATE INDEX "idx_repository_owner" ON "repository" ("owner_id");
CREATE INDEX "idx_repository_visibility" ON "repository" ("visibility");

CREATE TABLE IF NOT EXISTS "repository_file" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "repository_id" uuid NOT NULL,
  "branch_id" uuid NOT NULL,
  "path" varchar(512) NOT NULL,
  "file_name" varchar(256) NOT NULL,
  "is_directory" boolean NOT NULL DEFAULT false,
  "content" text,
  "size" bigint NOT NULL DEFAULT 0,
  "last_commit_id" uuid,
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "repository_file" IS '仓库文件树节点：支持在线编辑。';
COMMENT ON COLUMN "repository_file"."id" IS '主键UUID。';
COMMENT ON COLUMN "repository_file"."repository_id" IS '所属仓库ID，关联repository.id。';
COMMENT ON COLUMN "repository_file"."branch_id" IS '所属分支ID，关联branch.id。';
COMMENT ON COLUMN "repository_file"."path" IS '文件路径（如src/main.cj）。';
COMMENT ON COLUMN "repository_file"."file_name" IS '文件名。';
COMMENT ON COLUMN "repository_file"."is_directory" IS '是否目录。';
COMMENT ON COLUMN "repository_file"."content" IS '文件内容（目录为NULL）。';
COMMENT ON COLUMN "repository_file"."size" IS '文件大小字节数。';
COMMENT ON COLUMN "repository_file"."last_commit_id" IS '最后修改提交ID，关联commit.id。';
COMMENT ON COLUMN "repository_file"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "repository_file"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "repository_file"."created_at" IS '创建时间。';
COMMENT ON COLUMN "repository_file"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "repository_file"."deleted_at" IS '软删除时间。';
CREATE INDEX "idx_repo_file_branch_path" ON "repository_file" ("branch_id", "path");

CREATE TABLE IF NOT EXISTS "retrievers" (
  "id" varchar(36) NOT NULL DEFAULT gen_random_uuid(),
  "name" varchar(200) NOT NULL,
  "type" varchar(20) NOT NULL DEFAULT 'markdown'::character varying,
  "source_path" varchar(500) NOT NULL,
  "embedding_model" varchar(100) NOT NULL DEFAULT 'text-embedding-3-small'::character varying,
  "config" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "status" varchar(20) NOT NULL DEFAULT 'active'::character varying,
  "description" text,
  "creator" varchar(36),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "retrievers" IS 'RAG检索器定义表';
COMMENT ON COLUMN "retrievers"."type" IS '检索器类型：markdown/sqlite/sqlite_table';
COMMENT ON COLUMN "retrievers"."source_path" IS '数据源路径';
CREATE INDEX "idx_retrievers_type" ON "retrievers" ("type");

CREATE TABLE IF NOT EXISTS "review" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "score" integer NOT NULL,
  "description" text NOT NULL,
  "creator_name" text NOT NULL,
  "group_id" uuid,
  "link" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "creator" uuid,
  "deleted_at" timestamptz,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON COLUMN "review"."created_at" IS '创建时间';
COMMENT ON COLUMN "review"."creator" IS '创建人';
COMMENT ON COLUMN "review"."deleted_at" IS '删除时间';
COMMENT ON COLUMN "review"."updated_at" IS '更新时间';
CREATE UNIQUE INDEX "unique_reviewer_per_group" ON "review" ("creator_name", "group_id");

CREATE TABLE IF NOT EXISTS "role_has_permission" (
  "role_id" uuid NOT NULL,
  "permission_name" text NOT NULL,
  "status" integer NOT NULL DEFAULT 0,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("role_id", "permission_name")
);

