CREATE TABLE IF NOT EXISTS "sdd_projects" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "feature_name" varchar(64) NOT NULL,
  "title" varchar(256),
  "task_id" uuid,
  "current_stage" varchar(32) NOT NULL DEFAULT 'init'::character varying,
  "status" varchar(20) NOT NULL DEFAULT 'running'::character varying,
  "enable_research" boolean NOT NULL DEFAULT false,
  "round" integer NOT NULL DEFAULT 1,
  "payload" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "creator" uuid,
  "owner_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz
);
COMMENT ON TABLE "sdd_projects" IS 'SDD规范驱动开发工程实例：feature_name唯一，current_stage取值 init/research/spec/design/task/code/test/done';
COMMENT ON COLUMN "sdd_projects"."task_id" IS '回指 agent_tasks.id（权威态）';
COMMENT ON COLUMN "sdd_projects"."round" IS '当前轮次，revise回退重做时递增';
COMMENT ON COLUMN "sdd_projects"."owner_user_id" IS '归属者，遵循双账号身份约定（空串转NULL）';
CREATE UNIQUE INDEX "uq_sdd_projects_feature" ON "sdd_projects" ("feature_name");

CREATE TABLE IF NOT EXISTS "sensitive_word" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "word" text NOT NULL,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sensitive_word" IS '敏感词';
COMMENT ON COLUMN "sensitive_word"."word" IS '词汇';
COMMENT ON COLUMN "sensitive_word"."creator" IS '创建人';
COMMENT ON COLUMN "sensitive_word"."created_at" IS '创建时间';
COMMENT ON COLUMN "sensitive_word"."updated_at" IS '更新时间';
COMMENT ON COLUMN "sensitive_word"."deleted_at" IS '删除时间';

CREATE TABLE IF NOT EXISTS "skill_compositions" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "name" varchar(100) NOT NULL,
  "description" varchar(1024),
  "definition" jsonb NOT NULL,
  "source_path" varchar(500),
  "template_ref" varchar(100),
  "is_template" boolean NOT NULL DEFAULT false,
  "sync_status" varchar(20) NOT NULL DEFAULT 'synced'::character varying,
  "creator" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz DEFAULT NULL::timestamp with time zone,
  PRIMARY KEY ("id")
);
