  "view_count" bigint NOT NULL DEFAULT 0,
  "modify_count" bigint NOT NULL DEFAULT 0,
  "success_count" bigint NOT NULL DEFAULT 0,
  "failure_count" bigint NOT NULL DEFAULT 0,
  "state" varchar(20) NOT NULL DEFAULT 'experimental'::character varying,
  "avg_execution_time_ms" double precision NOT NULL DEFAULT 0.0,
  "user_rating" double precision NOT NULL DEFAULT 0.0,
  "last_used_at" timestamptz,
  "stats_detail" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz
);
COMMENT ON TABLE "skill_usage_stats" IS '技能使用统计表。存储技能的使用次数、成功率、状态等统计信息，支持技能自进化状态流转。';
COMMENT ON COLUMN "skill_usage_stats"."skill_name" IS '技能名称（唯一）';
COMMENT ON COLUMN "skill_usage_stats"."use_count" IS '使用次数';
COMMENT ON COLUMN "skill_usage_stats"."view_count" IS '查看次数';
COMMENT ON COLUMN "skill_usage_stats"."modify_count" IS '修改次数';
COMMENT ON COLUMN "skill_usage_stats"."success_count" IS '成功次数';
COMMENT ON COLUMN "skill_usage_stats"."failure_count" IS '失败次数';
COMMENT ON COLUMN "skill_usage_stats"."state" IS '技能状态：experimental/stable/recommended/deprecated/retired';
COMMENT ON COLUMN "skill_usage_stats"."avg_execution_time_ms" IS '平均执行耗时(毫秒)';
COMMENT ON COLUMN "skill_usage_stats"."user_rating" IS '用户评分(0.0-5.0)';
COMMENT ON COLUMN "skill_usage_stats"."last_used_at" IS '最近使用时间';
COMMENT ON COLUMN "skill_usage_stats"."stats_detail" IS '统计详情(JSON)';
CREATE UNIQUE INDEX "idx_skill_usage_stats_name" ON "skill_usage_stats" ("skill_name");
CREATE INDEX "idx_skill_usage_stats_state" ON "skill_usage_stats" ("state");

