CREATE TABLE IF NOT EXISTS "sub_agent_invocations" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "parent_task_id" uuid,
  "task_id" uuid,
  "agent_id" uuid NOT NULL,
  "skill_name" varchar(128),
  "stage" varchar(64),
  "mode" varchar(20) NOT NULL DEFAULT 'isolated'::character varying,
  "input_json" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "output_json" jsonb,
  "status" varchar(20) NOT NULL DEFAULT 'running'::character varying,
  "duration_ms" bigint,
  "error_message" text,
  "contract_type" varchar(64),
  "verify_passed" boolean,
  "verify_errors" text,
  "attempt" integer NOT NULL DEFAULT 1,
  "prompt_tokens" bigint NOT NULL DEFAULT 0,
  "completion_tokens" bigint NOT NULL DEFAULT 0,
  "total_tokens" bigint NOT NULL DEFAULT 0,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz
);
COMMENT ON TABLE "sub_agent_invocations" IS '子agent派单留痕：入参/出参/耗时/契约校验结果/token成本，可按stage聚合派生ROI';
COMMENT ON COLUMN "sub_agent_invocations"."parent_task_id" IS '所属SDD工程根任务(agent_tasks.id)';
COMMENT ON COLUMN "sub_agent_invocations"."task_id" IS '本次派单所建的agent_tasks子任务';
COMMENT ON COLUMN "sub_agent_invocations"."stage" IS 'SDD阶段：research/spec/design/task/code/test';
COMMENT ON COLUMN "sub_agent_invocations"."mode" IS '上下文交接模式：isolated(上下文内联) / path_ref(超限降级为路径引用)';
COMMENT ON COLUMN "sub_agent_invocations"."contract_type" IS '期望输出契约，取自agents.default_output_types；为空时标contract_absent并降级为非空校验';
COMMENT ON COLUMN "sub_agent_invocations"."attempt" IS '第几次尝试，契约校验失败自动重派时递增，首次为1；上限2次';
COMMENT ON COLUMN "sub_agent_invocations"."total_tokens" IS '本次派生总token，取不到记0并在error_message标token_missing';
CREATE INDEX "idx_sub_agent_invocations_parent" ON "sub_agent_invocations" ("parent_task_id");
CREATE INDEX "idx_sub_agent_invocations_stage" ON "sub_agent_invocations" ("skill_name", "stage");

CREATE TABLE IF NOT EXISTS "sync_log" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "entity_type" varchar(50) NOT NULL,
  "source_path" varchar(512) NOT NULL,
  "operation" varchar(30) NOT NULL,
  "direction" varchar(20) NOT NULL,
  "status" varchar(20) NOT NULL,
  "message" varchar(1000),
  "error_detail" varchar(4000),
  "sync_source" varchar(20) NOT NULL,
  "duration_ms" integer,
  "creator" uuid,
  "created_at" timestamptz DEFAULT now(),
  "updated_at" timestamptz DEFAULT now(),
  "deleted_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sync_log" IS '同步日志表，记录文件系统与数据库同步操作的详细日志';
COMMENT ON COLUMN "sync_log"."entity_type" IS '实体类型: agent, agent_skill';
COMMENT ON COLUMN "sync_log"."source_path" IS '实体文件路径（相对路径）';
COMMENT ON COLUMN "sync_log"."operation" IS '操作类型: create, update, delete, sync';
COMMENT ON COLUMN "sync_log"."direction" IS '同步方向: fs_to_db(文件→数据库), db_to_fs(数据库→文件)';
COMMENT ON COLUMN "sync_log"."status" IS '状态: success, failed';
COMMENT ON COLUMN "sync_log"."message" IS '操作消息';
COMMENT ON COLUMN "sync_log"."error_detail" IS '错误详情（失败时记录）';
COMMENT ON COLUMN "sync_log"."sync_source" IS '同步源标记: business(业务操作), sync_system(同步系统), manual(手动), startup(启动初始化)';
COMMENT ON COLUMN "sync_log"."duration_ms" IS '同步耗时(毫秒)';
COMMENT ON COLUMN "sync_log"."creator" IS '创建人/操作者';
COMMENT ON COLUMN "sync_log"."created_at" IS '日志创建时间';
COMMENT ON COLUMN "sync_log"."updated_at" IS '更新时间';
COMMENT ON COLUMN "sync_log"."deleted_at" IS '删除时间(软删除)';
CREATE INDEX "idx_sync_log_direction" ON "sync_log" ("direction");
CREATE INDEX "idx_sync_log_entity" ON "sync_log" ("entity_type", "source_path");
CREATE INDEX "idx_sync_log_status" ON "sync_log" ("status");
CREATE INDEX "idx_sync_log_time" ON "sync_log" ("created_at");

