CREATE INDEX "idx_task_settlements_status" ON "task_settlements" ("settlement_status");
CREATE INDEX "idx_task_settlements_task" ON "task_settlements" ("task_id");

CREATE TABLE IF NOT EXISTS "tasks" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "title" varchar(200) NOT NULL,
  "description" text NOT NULL,
  "task_type" varchar(20) NOT NULL DEFAULT 'development'::character varying,
  "task_status" varchar(20) NOT NULL DEFAULT 'open'::character varying,
  "priority" varchar(20) NOT NULL DEFAULT 'normal'::character varying,
  "company_id" uuid,
  "creator_id" uuid NOT NULL,
  "assignee_id" uuid,
  "participant_count" integer NOT NULL DEFAULT 0,
  "follower_count" integer NOT NULL DEFAULT 0,
  "view_count" integer NOT NULL DEFAULT 0,
  "comment_count" integer NOT NULL DEFAULT 0,
  "reward_type" varchar(20) DEFAULT 'none'::character varying,
  "reward_amount" varchar(100),
  "deadline" timestamptz,
  "started_at" timestamptz,
  "completed_at" timestamptz,
  "tags" jsonb DEFAULT '[]'::jsonb,
  "skills_required" jsonb DEFAULT '[]'::jsonb,
  "attachments" jsonb DEFAULT '[]'::jsonb,
  "extra_data" jsonb DEFAULT '{}'::jsonb,
  "creator" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "reward_points" bigint NOT NULL DEFAULT 0,
  "max_participants" integer NOT NULL DEFAULT 1,
  "accept_deadline" timestamptz,
  "settlement_status" varchar(20) NOT NULL DEFAULT 'pending'::character varying,
  "points_frozen" bigint NOT NULL DEFAULT 0,
  "points_settled" bigint NOT NULL DEFAULT 0,
  "points_refunded" bigint NOT NULL DEFAULT 0,
  "review_status" varchar(20) NOT NULL DEFAULT 'pending'::character varying,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "tasks" IS 'AI Builder任务表';
COMMENT ON COLUMN "tasks"."title" IS '任务标题';
COMMENT ON COLUMN "tasks"."description" IS '任务详细描述';
COMMENT ON COLUMN "tasks"."task_type" IS '任务类型：development/design/marketing/other';
COMMENT ON COLUMN "tasks"."task_status" IS '任务状态：open(待承接)/in_progress(进行中)/submitted(已提交)/reviewing(审核中)/completed(已完成)/closed(已关闭)/expired(已过期)';
COMMENT ON COLUMN "tasks"."priority" IS '优先级：low/normal/high/urgent';
COMMENT ON COLUMN "tasks"."company_id" IS '关联组织ID';
COMMENT ON COLUMN "tasks"."creator_id" IS '创建者用户ID';
COMMENT ON COLUMN "tasks"."assignee_id" IS '负责人/承接者用户ID';
COMMENT ON COLUMN "tasks"."participant_count" IS '参与者数量';
COMMENT ON COLUMN "tasks"."follower_count" IS '关注者数量';
COMMENT ON COLUMN "tasks"."view_count" IS '浏览次数';
COMMENT ON COLUMN "tasks"."comment_count" IS '评论数';
COMMENT ON COLUMN "tasks"."reward_type" IS '奖励类型：money/reputation/equity/none';
COMMENT ON COLUMN "tasks"."reward_amount" IS '奖励金额/数量';
COMMENT ON COLUMN "tasks"."deadline" IS '截止时间';
COMMENT ON COLUMN "tasks"."tags" IS '标签（JSON数组）';
COMMENT ON COLUMN "tasks"."skills_required" IS '所需技能（JSON数组）';
COMMENT ON COLUMN "tasks"."reward_points" IS '奖励积分总数';
COMMENT ON COLUMN "tasks"."max_participants" IS '最大承接人数，1表示单人任务';
COMMENT ON COLUMN "tasks"."accept_deadline" IS '承接截止时间（超期无人接则退还积分）';
COMMENT ON COLUMN "tasks"."settlement_status" IS '结算状态：pending(待结算)/settling(结算中)/settled(已结算)/refunded(已退还)/partial_settled(部分结算)/cancelled(已取消)';
COMMENT ON COLUMN "tasks"."points_frozen" IS '冻结积分数（发布时冻结）';
COMMENT ON COLUMN "tasks"."points_settled" IS '已结算积分数';
COMMENT ON COLUMN "tasks"."points_refunded" IS '已退还积分数';
COMMENT ON COLUMN "tasks"."review_status" IS '审核状态：pending(待审核)/reviewing(审核中)/approved(审核通过)/rejected(审核拒绝)';
CREATE INDEX "idx_tasks_accept_deadline" ON "tasks" ("accept_deadline");
CREATE INDEX "idx_tasks_company_id" ON "tasks" ("company_id");
CREATE INDEX "idx_tasks_created_at" ON "tasks" ("created_at");
CREATE INDEX "idx_tasks_creator_id" ON "tasks" ("creator_id");
CREATE INDEX "idx_tasks_review_status" ON "tasks" ("review_status");
CREATE INDEX "idx_tasks_settlement_status" ON "tasks" ("settlement_status");
CREATE INDEX "idx_tasks_task_status" ON "tasks" ("task_status");

