CREATE TABLE IF NOT EXISTS "user_has_tasks" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "user_id" uuid NOT NULL,
  "task_id" uuid NOT NULL,
  "relation_type" varchar(20) NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamptz,
  "creator" uuid,
  "join_status" varchar(20) NOT NULL DEFAULT 'applied'::character varying,
  "submission_content" text,
  "submission_attachments" jsonb DEFAULT '[]'::jsonb,
  "submitted_at" timestamptz,
  "review_status" varchar(20) NOT NULL DEFAULT 'pending'::character varying,
  "review_comment" text,
  "reviewed_at" timestamptz,
  "reviewer_id" uuid,
  "allocation_ratio" numeric(5,2) NOT NULL DEFAULT 100.00,
  "points_earned" bigint NOT NULL DEFAULT 0,
  "settled_at" timestamptz,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "user_has_tasks" IS '用户-任务关联表';
COMMENT ON COLUMN "user_has_tasks"."relation_type" IS '关系类型：creator(创建者)/assignee(承接者)/participant(参与者)/follower(关注者)/watcher(观察者)';
COMMENT ON COLUMN "user_has_tasks"."creator" IS '创建人ID';
COMMENT ON COLUMN "user_has_tasks"."join_status" IS '参与状态：applied(申请中)/accepted(已接受)/submitted(已提交)/approved(审核通过)/rejected(审核拒绝)/completed(已完成)/left(已退出)';
COMMENT ON COLUMN "user_has_tasks"."submission_content" IS '提交的成果内容';
COMMENT ON COLUMN "user_has_tasks"."submission_attachments" IS '提交的附件（JSON数组）';
COMMENT ON COLUMN "user_has_tasks"."submitted_at" IS '提交时间';
COMMENT ON COLUMN "user_has_tasks"."review_status" IS '审核状态：pending(待审核)/approved(通过)/rejected(拒绝)';
COMMENT ON COLUMN "user_has_tasks"."review_comment" IS '审核意见';
COMMENT ON COLUMN "user_has_tasks"."reviewed_at" IS '审核时间';
COMMENT ON COLUMN "user_has_tasks"."reviewer_id" IS '审核人ID';
COMMENT ON COLUMN "user_has_tasks"."allocation_ratio" IS '分配比例（百分比，0-100），多人任务时由公司设置';
COMMENT ON COLUMN "user_has_tasks"."points_earned" IS '实际获得的积分';
COMMENT ON COLUMN "user_has_tasks"."settled_at" IS '结算时间';
CREATE UNIQUE INDEX "user_has_tasks_user_id_task_id_relation_type_key" ON "user_has_tasks" ("user_id", "task_id", "relation_type");
CREATE INDEX "idx_uht_join_status" ON "user_has_tasks" ("join_status");
CREATE INDEX "idx_uht_review_status" ON "user_has_tasks" ("review_status");
CREATE INDEX "idx_uht_reviewer_id" ON "user_has_tasks" ("reviewer_id");
CREATE INDEX "idx_uht_settled_at" ON "user_has_tasks" ("settled_at");
CREATE INDEX "idx_uht_task_id" ON "user_has_tasks" ("task_id");
CREATE INDEX "idx_uht_task_relation" ON "user_has_tasks" ("task_id", "relation_type");
CREATE INDEX "idx_uht_user_id" ON "user_has_tasks" ("user_id");

