CREATE TABLE IF NOT EXISTS "validation_rule" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "worksheet_id" uuid NOT NULL,
  "range_start" varchar(10) NOT NULL,
  "range_end" varchar(10) NOT NULL,
