COMMENT ON COLUMN "validation_rule"."range_end" IS '区域结束坐标（如A10）。';
COMMENT ON COLUMN "validation_rule"."validation_type" IS '验证类型：dropdown/numeric。';
COMMENT ON COLUMN "validation_rule"."constraints" IS '下拉列表值集合或数值范围{min,max}。';
COMMENT ON COLUMN "validation_rule"."error_message" IS '验证失败提示。';
COMMENT ON COLUMN "validation_rule"."creator" IS '创建者UUID，关联uctoo_user.id，行级权限。';
COMMENT ON COLUMN "validation_rule"."owner_user_id" IS '行级权限归属用户ID。';
COMMENT ON COLUMN "validation_rule"."created_at" IS '创建时间。';
COMMENT ON COLUMN "validation_rule"."updated_at" IS '更新时间。';
COMMENT ON COLUMN "validation_rule"."deleted_at" IS '软删除时间。';
CREATE INDEX "idx_validation_worksheet" ON "validation_rule" ("worksheet_id");

