CREATE TABLE IF NOT EXISTS "wechatpay_transaction" (
  "id" uuid NOT NULL DEFAULT gen_random_uuid(),
  "notify_id" text NOT NULL,
  "transaction_id" text NOT NULL,
  "mchid" text NOT NULL,
  "appid" text NOT NULL,
  "out_trade_no" text NOT NULL,
  "trade_state" text NOT NULL,
  "trade_state_desc" text NOT NULL,
  "bank_type" text NOT NULL,
  "trade_type" text NOT NULL,
  "success_time" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "attach" text,
  "payer" text NOT NULL,
  "amount" text NOT NULL,
  "scene_info" text,
  "promotion_detail" text,
  "is_subscribe" text,
  "create_time" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
